import{_ as o,c as a,o as i,G as e,a as s}from"./chunks/framework.BwVZiZlf.js";const p=JSON.parse('{"title":"Nobody Likes Being Sold to","description":"","frontmatter":{"date":"2025-04-12T00:00:00.000Z"},"headers":[],"relativePath":"blog/2025/04/12/nobody-likes-being-sold-to.md","filePath":"blog/2025/04/12/nobody-likes-being-sold-to.md","lastUpdated":1786674252000}'),n={name:"blog/2025/04/12/nobody-likes-being-sold-to.md"};function d(l,t,r,h,c,m){return i(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1744416000000"},t[0]||(t[0]=[e("h1",{id:"nobody-likes-being-sold-to",tabindex:"-1"},[s("Nobody Likes Being Sold to "),e("a",{class:"header-anchor",href:"#nobody-likes-being-sold-to","aria-label":'Permalink to "Nobody Likes Being Sold to"'},"​")],-1),e("p",null,"After my son's class ended, his teacher asked me to stay behind to talk about the summer camp. I could tell from his expression that this wasn't going to be a casual conversation.",-1),e("p",null,"A few weeks earlier, my son told me he didn't want to go to the summer camp organized by the Wushu school. He had been taking Wushu classes for about a year, and while he enjoyed the regular sessions, he wasn't enthusiastic about an intensive summer program. For the sake of my son's teacher, I patiently listened to the supervisor's introduction of the summer camp. He spoke at length about character building, discipline development, and the unique experiences the children would have. At the end, I politely said that I would tell him when we decided to go. His demeanor immediately changed as he said that today was the last day to determine, and repeated many times that this was the last chance to decide to participate in it.",-1),e("p",null,`The high-pressure sales tactics made me uncomfortable. I remembered what Musk said: "Marketing is selling bad products to people who don't need them." I felt like he was trying to sell me something that neither my son nor I wanted. The urgency felt artificial - a classic sales technique to force quick decisions without proper consideration.`,-1),e("p",null,`On the way home, I asked my son if he would like to attend that summer camp. He said he didn't know, his voice uncertain. I decided to break down the offer objectively: "This summer camp is actually 5 days of military training plus 2 days of travel. The cost is 7000 RMB. If it were me, I would definitely not go. It's just a waste of money. That's almost 1000 RMB per day for activities you're not even excited about." He seemed relieved when I put it that way and firmly said he would not go.`,-1),e("p",null,'The experience reminded me how important it is to teach children about making informed decisions and not giving in to pressure tactics. Sometimes saying "no" is the best decision, especially when someone is trying too hard to make you say "yes."',-1)]))}const y=o(n,[["render",d]]);export{p as __pageData,y as default};
